 58→bool ChatServer::initListenSocket() {
 59→    // 1. 创建 TCP socket
 60→    listen_fd_ = socket(AF_INET, SOCK_STREAM, 0);
 61→    if (listen_fd_ < 0) {
 62→        std::cerr << "[Server] socket() 失败: " << strerror(errno) << std::endl;
 63→        return false;
 64→    }
 65→
 66→    // 2. 设置 SO_REUSEADDR，避免服务器重启时 "Address already in use"
 67→    int opt = 1;
 68→    setsockopt(listen_fd_, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
