 70→    // 3. 绑定地址
 71→    struct sockaddr_in addr{};
 72→    addr.sin_family      = AF_INET;
 73→    addr.sin_addr.s_addr = INADDR_ANY;          // 监听所有网卡
 74→    addr.sin_port        = htons(listen_port_);
 75→
 76→    if (bind(listen_fd_, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
 77→        std::cerr << "[Server] bind() 失败: " << strerror(errno) << std::endl;
 78→        close(listen_fd_);
 79→        listen_fd_ = -1;
 80→        return false;
