 83→    // 4. 开始监听，backlog = 128
 84→    if (listen(listen_fd_, 128) < 0) {
 85→        std::cerr << "[Server] listen() 失败: " << strerror(errno) << std::endl;
 86→        close(listen_fd_);
 87→        listen_fd_ = -1;
 88→        return false;
 89→    }
 90→
 91→    // 5. 设置为非阻塞
 92→    setNonBlocking(listen_fd_);
 93→
 94→    std::cout << "[Server] 监听 socket 创建成功，端口: " << listen_port_ << std::endl;
 95→    return true;
