113→int ChatServer::run() {
114→    // 忽略 SIGPIPE，避免向已断开的客户端写数据时导致进程退出
115→    signal(SIGPIPE, SIG_IGN);
116→
117→    if (!initListenSocket()) return -1;
118→    if (!initEpoll()) return -1;
