127→        int nfds = epoll_wait(epoll_fd_, events_, MAX_EVENTS, 1000);
128→        if (nfds < 0) {
129→            if (errno == EINTR) continue;  // 被信号中断，重试
130→            std::cerr << "[Server] epoll_wait() 错误: " << strerror(errno) << std::endl;
131→            break;
