142→void ChatServer::handleEvents(int nfds) {
143→    for (int i = 0; i < nfds; ++i) {
144→        int fd = events_[i].data.fd;
145→        uint32_t ev = events_[i].events;
146→
147→        // 监听 socket 上有新连接
148→        if (fd == listen_fd_) {
149→            handleNewConnection();
150→        }
151→        // 客户端断开或错误
152→        else if (ev & (EPOLLHUP | EPOLLERR)) {
153→            handleClientDisconnect(fd);
154→        }
155→        // 客户端可读
156→        else if (ev & EPOLLIN) {
157→            handleClientRead(fd);
158→        }
159→        // 客户端可写（发送缓冲区有空间）
160→        else if (ev & EPOLLOUT) {
161→            handleClientWrite(fd);
162→        }
163→    }
164→}
