168→void ChatServer::handleNewConnection() {
169→    // 循环 accept 处理所有排队的连接（LT 模式下理论上一次 accept 一个即可，
170→    // 但循环 accept 可以提高效率）
171→    while (true) {
172→        struct sockaddr_in client_addr{};
173→        socklen_t addr_len = sizeof(client_addr);
174→        int client_fd = accept(listen_fd_, (struct sockaddr*)&client_addr, &addr_len);
175→
176→        if (client_fd < 0) {
177→            if (errno == EAGAIN || errno == EWOULDBLOCK) {
178→                break;  // 所有连接都 accept 完了
179→            }
180→            std::cerr << "[Server] accept() 错误: " << strerror(errno) << std::endl;
181→            break;
182→        }
183→
184→        // 设置客户端 socket 为非阻塞
185→        setNonBlocking(client_fd);
186→
187→        // 将客户端加入 epoll，监听可读事件
188→        epollCtl(client_fd, EPOLLIN, EPOLL_CTL_ADD);
189→
190→        // 创建客户端信息并保存
191→        clients_.emplace(client_fd, ClientInfo(client_fd));
192→
193→        char ip_str[INET_ADDRSTRLEN];
194→        inet_ntop(AF_INET, &client_addr.sin_addr, ip_str, sizeof(ip_str));
195→        std::cout << "[Server] 新连接: fd=" << client_fd
196→                  << " 来自 " << ip_str << ":" << ntohs(client_addr.sin_port)
197→                  << "，等待注册用户名..." << std::endl;
198→    }
199→}
