201→// ===================== 客户端可读处理 =====================
202→
203→void ChatServer::handleClientRead(int fd) {
204→    auto it = clients_.find(fd);
205→    if (it == clients_.end()) return;
206→
207→    ClientInfo& client = it->second;
208→    char buf[4096];
209→
210→    // 循环读取所有可用数据
211→    while (true) {
212→        ssize_t n = recv(fd, buf, sizeof(buf), 0);
213→
214→        if (n < 0) {
215→            if (errno == EAGAIN || errno == EWOULDBLOCK) {
216→                break;  // 数据读完了
217→            }
218→            std::cerr << "[Server] recv() 错误 fd=" << fd << ": " << strerror(errno) << std::endl;
219→            handleClientDisconnect(fd);
220→            return;
221→        }
222→        if (n == 0) {
223→            // 对端关闭连接
224→            handleClientDisconnect(fd);
225→            return;
226→        }
227→
228→        // 追加到接收缓冲区
229→        client.recv_buf.insert(client.recv_buf.end(), buf, buf + n);
230→    }
231→
232→    // 尝试从接收缓冲区解析完整消息
233→    while (client.recv_buf.size() >= HEADER_SIZE) {
234→        // 解析消息头
235→        MessageHeader hdr;
236→        if (!hdr.deserialize(client.recv_buf.data())) {
237→            std::cerr << "[Server] 消息协议版本不匹配 fd=" << fd << std::endl;
238→            handleClientDisconnect(fd);
239→            return;
240→        }
241→
242→        // 检查消息体长度是否合法
243→        if (hdr.length > MAX_BODY_SIZE) {
244→            std::cerr << "[Server] 消息体过大 fd=" << fd << " len=" << hdr.length << std::endl;
245→            handleClientDisconnect(fd);
246→            return;
247→        }
248→
249→        // 检查接收缓冲区是否有完整消息
250→        size_t total = HEADER_SIZE + hdr.length;
251→        if (client.recv_buf.size() < total) {
252→            break;  // 数据不完整，等待更多数据
253→        }
254→
255→        // 提取消息体
256→        std::string body;
257→        if (hdr.length > 0) {
258→            body.assign(client.recv_buf.begin() + HEADER_SIZE,
259→                        client.recv_buf.begin() + total);
260→        }
261→
262→        // 处理这条完整消息
263→        processMessage(fd, hdr.type, body);
264→
265→        // 从缓冲区移除已处理的数据
266→        client.recv_buf.erase(client.recv_buf.begin(), client.recv_buf.begin() + total);
267→    }
268→}
