272→void ChatServer::handleClientWrite(int fd) {
273→    auto it = clients_.find(fd);
274→    if (it == clients_.end()) return;
275→
276→    ClientInfo& client = it->second;
277→
278→    // 发送缓冲区中的数据
279→    while (!client.send_buf.empty()) {
280→        ssize_t n = send(fd, client.send_buf.data(), client.send_buf.size(), MSG_NOSIGNAL);
281→        if (n < 0) {
282→            if (errno == EAGAIN || errno == EWOULDBLOCK) {
283→                break;  // 发送缓冲区满，下次再试
284→            }
285→            std::cerr << "[Server] send() 错误 fd=" << fd << ": " << strerror(errno) << std::endl;
286→            handleClientDisconnect(fd);
287→            return;
288→        }
289→        // 移除已发送的数据
290→        client.send_buf.erase(client.send_buf.begin(), client.send_buf.begin() + n);
291→    }
292→
293→    // 如果发送缓冲区已空，取消 EPOLLOUT 监听（避免空转浪费 CPU）
294→    if (client.send_buf.empty()) {
295→        epollCtl(fd, EPOLLIN, EPOLL_CTL_MOD);
296→    }
297→}
