352→// 处理用户注册
353→void ChatServer::processRegister(int fd, const std::string& username) {
354→    auto it = clients_.find(fd);
355→    if (it == clients_.end()) return;
356→
357→    ClientInfo& client = it->second;
358→
359→    // 检查是否已注册
360→    if (client.registered) {
361→        sendToClient(fd, MessageBuilder::errorMsg("你已经注册过了"));
362→        return;
363→    }
364→
365→    // 校验用户名
366→    if (username.empty() || username.size() > MAX_USERNAME_LEN) {
367→        sendToClient(fd, MessageBuilder::errorMsg("用户名长度必须在1-32之间"));
368→        return;
369→    }
370→
371→    // 检查用户名是否包含非法字符（不允许包含空格和换行）
372→    for (char c : username) {
373→        if (c == ' ' || c == '\n' || c == '\r' || c == '\0') {
374→            sendToClient(fd, MessageBuilder::errorMsg("用户名不能包含空格或换行符"));
375→            return;
376→        }
377→    }
378→
379→    // 检查用户名唯一性
380→    if (usernames_.count(username) > 0) {
381→        sendToClient(fd, MessageBuilder::errorMsg("用户名已被占用，请选择其他用户名"));
382→        return;
383→    }
384→
385→    // 注册成功
386→    client.username = username;
387→    client.registered = true;
388→    usernames_.insert(username);
389→
390→    std::cout << "[Server] 用户注册成功: " << username << " (fd=" << fd << ")" << std::endl;
391→
392→    // 发送确认消息给该客户端
393→    sendToClient(fd, MessageBuilder::ackMsg("注册成功! 欢迎 " + username));
394→
395→    // 广播上线通知给所有其他人
396→    std::string notice = "[系统] " + username + " 加入了聊天室";
397→    broadcast(MessageBuilder::systemMsg(notice), fd);
398→
399→    // 广播更新后的在线用户列表
400→    broadcastOnlineUsers();
401→}
