426→// 将数据追加到客户端的发送缓冲区，并注册 EPOLLOUT 事件
427→void ChatServer::sendToClient(int fd, const std::vector<uint8_t>& data) {
428→    auto it = clients_.find(fd);
429→    if (it == clients_.end()) return;
430→
431→    ClientInfo& client = it->second;
432→
433→    // 如果发送缓冲区为空，先尝试直接发送
434→    if (client.send_buf.empty()) {
435→        ssize_t n = send(fd, data.data(), data.size(), MSG_NOSIGNAL);
436→        if (n >= 0) {
437→            // 全部发送成功
438→            if (static_cast<size_t>(n) == data.size()) return;
439→            // 部分发送，剩余数据放入缓冲区
440→            client.send_buf.insert(client.send_buf.end(),
441→                                   data.begin() + n, data.end());
442→        } else {
443→            if (errno == EAGAIN || errno == EWOULDBLOCK) {
444→                // 发送缓冲区满，放入发送缓冲区
445→                client.send_buf.assign(data.begin(), data.end());
446→            } else {
447→                handleClientDisconnect(fd);
448→                return;
449→            }
450→        }
451→    } else {
452→        // 发送缓冲区还有数据，直接追加
453→        client.send_buf.insert(client.send_buf.end(), data.begin(), data.end());
454→    }
455→
456→    // 注册 EPOLLOUT 事件，下次 epoll_wait 返回时继续发送
457→    epollCtl(fd, EPOLLIN | EPOLLOUT, EPOLL_CTL_MOD);
458→}
